import Foundation
import GRDB

/// Semantic versions of the timeline context used by a rewrite, scoped to its window.
struct TimelineRewriteSnapshot: Equatable, Sendable {
  let startTs: Int
  let endTs: Int
  let cardVersions: [String]
  let pendingVersions: [String]
}

private struct TimelineSnapshotRow {
  let id: Int64
  let batchId: Int64?
  let start: Int
  let end: Int
  let isFailurePlaceholder: Bool

  init(_ version: String, isCard: Bool) throws {
    // These arrays are generated by the snapshot SQL below; preserve SQL NULLs
    // and field boundaries instead of concatenating potentially ambiguous text.
    guard let values = try JSONSerialization.jsonObject(with: Data(version.utf8)) as? [Any],
      values.count == (isCard ? 13 : 8), let id = values[0] as? NSNumber,
      let start = values[isCard ? 4 : 2] as? NSNumber,
      let end = values[isCard ? 5 : 3] as? NSNumber else {
      throw TimelineCardReplacementError.timelineChanged
    }
    self.id = id.int64Value
    batchId = (values[1] as? NSNumber)?.int64Value
    self.start = start.intValue
    self.end = end.intValue
    isFailurePlaceholder = isCard && values[9] as? String == "System"
      && values[7] as? String == "Processing failed"
  }
}

extension StorageManager {
  func captureTimelineRewriteSnapshot(from: Int, to: Int) throws -> TimelineRewriteSnapshot {
    try timedRead("captureTimelineRewriteSnapshot") { db in
      try captureTimelineRewriteSnapshot(in: db, from: from, to: to)
    }
  }

  /// A failed read cannot establish that the original context still matches.
  func timelineRewriteMatches(_ snapshot: TimelineRewriteSnapshot) -> Bool {
    (try? timedRead("timelineRewriteMatches") { db in
      try captureTimelineRewriteSnapshot(in: db, from: snapshot.startTs, to: snapshot.endTs) == snapshot
    }) ?? false
  }

  /// The baseline may cover a larger lookback than the spans this commit uses.
  func timelineRewriteMatches(
    in db: Database, snapshot: TimelineRewriteSnapshot,
    groups: [TimelineCardReplacementGroup], pendingToSave: [PendingTimelineEvidence],
    pendingToDelete: [Int64], markBatchAnalyzed: Bool, batchId: Int64,
    requiredCardIds: [Int64]
  ) throws -> Bool {
    // A baseline cannot protect writes outside the region it actually observed.
    // Fail closed if a future planner widens its rewrite beyond that baseline.
    guard groups.allSatisfy({
      Int($0.from.timeIntervalSince1970) >= snapshot.startTs
        && Int($0.to.timeIntervalSince1970) <= snapshot.endTs
    }), pendingToSave.allSatisfy({
      $0.startTs >= snapshot.startTs && $0.endTs < snapshot.endTs
    }) else { return false }
    let current = try captureTimelineRewriteSnapshot(in: db, from: snapshot.startTs, to: snapshot.endTs)
    let baselineCards = try snapshot.cardVersions.map { try TimelineSnapshotRow($0, isCard: true) }
    let baselinePending = try snapshot.pendingVersions.map { try TimelineSnapshotRow($0, isCard: false) }
    let deletedPendingIds = Set(pendingToDelete)
    let consumedCardIds = Set(requiredCardIds)
    guard consumedCardIds.isSubset(of: Set(baselineCards.map(\.id))),
      deletedPendingIds.isSubset(of: Set(baselinePending.map(\.id))) else { return false }
    var ranges = groups.map { (Int($0.from.timeIntervalSince1970), Int($0.to.timeIntervalSince1970)) }
    ranges += pendingToSave.map { ($0.startTs, $0.endTs) }
    ranges += baselinePending.filter { deletedPendingIds.contains($0.id) }.map { ($0.start, $0.end) }
    let batchOnly = groups.isEmpty && pendingToSave.isEmpty && pendingToDelete.isEmpty && markBatchAnalyzed

    func selected(_ row: TimelineSnapshotRow, isCard: Bool) -> Bool {
      if isCard && consumedCardIds.contains(row.id) { return true }
      if !isCard && deletedPendingIds.contains(row.id) { return true }
      if row.batchId == batchId {
        if batchOnly { return true }
        if isCard && markBatchAnalyzed && row.isFailurePlaceholder { return true }
      }
      return ranges.contains { from, to in
        // A zero-length pending fragment consumes its instant, including rows
        // spanning that instant and other fragments at the same instant.
        if from == to { return row.start <= from && (row.end > from || row.start == from) }
        return (row.start < to && row.end > from) || (row.start >= from && row.start < to)
      }
    }
    func versions(_ rows: [String], isCard: Bool) throws -> [String] {
      try rows.filter { selected(try TimelineSnapshotRow($0, isCard: isCard), isCard: isCard) }
    }
    return try versions(snapshot.cardVersions, isCard: true) == versions(current.cardVersions, isCard: true)
      && versions(snapshot.pendingVersions, isCard: false) == versions(current.pendingVersions, isCard: false)
  }

  /// Also used inside the commit transaction, before any mutation.
  func captureTimelineRewriteSnapshot(in db: Database, from: Int, to: Int) throws -> TimelineRewriteSnapshot {
    let arguments: StatementArguments = [to, from, from, to]
    let cards = try String.fetchAll(db, sql: """
      SELECT json_array(id, batch_id, start, end, start_ts, end_ts, day,
        title, summary, category, subcategory, detailed_summary, metadata)
      FROM timeline_cards
      WHERE is_deleted = 0
        AND ((start_ts < ? AND end_ts > ?) OR (start_ts >= ? AND start_ts < ?))
      ORDER BY id
      """, arguments: arguments)
    let pending = try String.fetchAll(db, sql: """
      SELECT json_array(p.id, p.batch_id, p.start_ts, p.end_ts, p.card_json,
        p.first_screenshot_id, p.last_screenshot_id,
        json((SELECT json_group_array(screenshot_id) FROM (
          SELECT screenshot_id FROM pending_timeline_sources
          WHERE pending_id = p.id ORDER BY screenshot_id
        ))))
      FROM pending_timeline_evidence p
      WHERE (p.start_ts < ? AND p.end_ts > ?) OR (p.start_ts >= ? AND p.start_ts < ?)
      ORDER BY p.id
      """, arguments: arguments)
    return TimelineRewriteSnapshot(startTs: from, endTs: to, cardVersions: cards, pendingVersions: pending)
  }
}
